#!/usr/bin/env bash
# Question 1: Which context may delete Secrets in ${Q1_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/kc/can-i
mkdir -p /opt/course/kc/can-i
chown -R ubuntu:ubuntu /opt/course
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
sign() {
  openssl genrsa -out "$work/$1.key" 2048 2>/dev/null
  openssl req -new -key "$work/$1.key" -subj "$2" -out "$work/$1.csr" 2>/dev/null
  openssl x509 -req -in "$work/$1.csr" -CA /etc/kubernetes/pki/ca.crt -CAkey /etc/kubernetes/pki/ca.key -CAserial "$work/ca.srl" -CAcreateserial -days "$3" -out "$work/$1.crt" 2>/dev/null
}
kc() { local f=$1; shift; kubectl --kubeconfig "$f" config "$@" >/dev/null; }
server=$(kubectl config view --minify -o jsonpath='{.clusters[0].cluster.server}')
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
f=/opt/course/kc/can-i/kubeconfig
kubectl -n "${Q1_NS}" delete rolebinding secret-admin secret-reader viewer --ignore-not-found >/dev/null
kubectl -n "${Q1_NS}" delete role secret-admin secret-reader --ignore-not-found >/dev/null
read -r admin reader viewer < <(shuf -e amber cobalt jade -n 3 | xargs)
kubectl -n "${Q1_NS}" create role secret-admin --verb=get,list,delete --resource=secrets >/dev/null
kubectl -n "${Q1_NS}" create rolebinding secret-admin --role=secret-admin --user="$admin" >/dev/null
kubectl -n "${Q1_NS}" create role secret-reader --verb=get,list --resource=secrets >/dev/null
kubectl -n "${Q1_NS}" create rolebinding secret-reader --role=secret-reader --user="$reader" >/dev/null
kubectl -n "${Q1_NS}" create rolebinding viewer --clusterrole=view --user="$viewer" >/dev/null
kc "$f" set-cluster kubernetes --server="$server" --certificate-authority=/etc/kubernetes/pki/ca.crt --embed-certs=true
for c in amber cobalt jade; do
  sign "$c" "/CN=$c/O=${Q1_NS}-team" "$(shuf -i 90-400 -n 1)"
  kc "$f" set-credentials "$c" --client-certificate="$work/$c.crt" --client-key="$work/$c.key" --embed-certs=true
  kc "$f" set-context "${Q1_NS}-$c" --cluster=kubernetes --user="$c" --namespace="${Q1_NS}"
done
kc "$f" use-context "${Q1_NS}-$viewer"
cp "/opt/course/kc/can-i/kubeconfig" "/var/tmp/cka-kc-can-i-kubeconfig"
chmod 600 "/var/tmp/cka-kc-can-i-kubeconfig"
chown -R ubuntu:ubuntu /opt/course/kc
: "${Q1_USER}" "${Q1_CTX}" "${Q1_NS}"
